struct Params {
  threshold: f32, // @default 1.2  Linear radiance where bloom starts.
  knee: f32, // @default 0.8  Softness of the threshold.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let color = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb;
  let brightness = max(color.r, max(color.g, color.b));
  let soft = clamp(brightness - params.threshold + params.knee, 0.0, 2.0 * params.knee);
  let weight = max(soft * soft / (4.0 * params.knee + 1e-4), brightness - params.threshold) / max(brightness, 1e-4);
  return vec4f(color * weight, 1.0);
}

struct Params {
  hotspot: f32, // @default 0.22  Radius of the hot spot (fraction of the image height).
  spill: f32, // @default 0.8  Radius of the spill.
  separation: f32, // @default 0.3  Distance between the two beams' centres (fraction of the image width).
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let unused = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).a * 0.0;
  // Two low beams side by side (the projector sits between a car's headlights): each wide,
  // flat on top (the cut-off), brightest a little below the axis.
  var value = 0.0;
  for (var k = 0; k < 2; k = k + 1) {
    let c = (uv - vec2f(0.5 + (f32(k) - 0.5) * params.separation, 0.56)) * vec2f(1.0, 2.0);
    let r = length(c);
    value = value + exp(-(r * r) / (2.0 * params.hotspot * params.hotspot)) + 0.25 * exp(-(r * r) / (2.0 * params.spill * params.spill));
  }
  value = value * mix(0.15, 1.0, smoothstep(0.38, 0.44, uv.y));
  // Fade to nothing at the image's border: a projector's frame edge must never draw a hard rectangle.
  let border = smoothstep(0.0, 0.12, uv.x) * smoothstep(1.0, 0.88, uv.x) * smoothstep(0.0, 0.15, uv.y) * smoothstep(1.0, 0.85, uv.y);
  value = value * border;
  return vec4f(vec3f(value) + vec3f(unused), 1.0);
}

struct Params {
  eye: vec3f, // @default 0  Camera position (drive from the camera).
  aim: vec3f, // @default 0  Camera look-at (drive from the camera).
  fov: f32, // @default 50  Camera vertical field of view, degrees.
  far: f32, // @default 400  Camera far plane (depth arrives as distance ÷ far).
  roll: f32, // @default 0  Camera roll, degrees (drive from the camera).
  focusDistance: f32, // @default 0  Distance in focus, metres; 0 focuses on whatever is at the frame's centre.
  aperture: f32, // @default 0.8  Blur strength: circle radius in pixels per unit of defocus.
  maxRadius: f32, // @default 14  Largest circle of confusion, pixels.
};
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

// T1383b: the camera's right vector with its ROLL — world up turned about the view axis by
// roll degrees (Rodrigues, right-handed about the camera's +z: the angle is negated about forward),
// exactly as camera.ts guardedRolledUp builds the render's view (T1433b).
fn rolledRight(forward: vec3f, rollDeg: f32) -> vec3f {
  var up = select(vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0), abs(forward.y) > 0.999);
  let t = radians(-rollDeg);
  up = up * cos(t) + cross(forward, up) * sin(t) + forward * dot(forward, up) * (1.0 - cos(t));
  return normalize(cross(forward, up));
}

struct View {
  forward: vec3f,
  right: vec3f,
  up: vec3f,
  tanHalf: f32,
  aspect: f32,
};

fn makeView() -> View {
  var v: View;
  v.forward = normalize(params.aim - params.eye);
  v.right = rolledRight(v.forward, params.roll);
  v.up = cross(v.right, v.forward);
  v.tanHalf = tan(radians(params.fov) * 0.5);
  v.aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  return v;
}

fn rayAt(v: View, uv: vec2f) -> vec3f {
  let ndc = vec2f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
  return normalize(v.forward + v.right * ndc.x * v.tanHalf * v.aspect + v.up * ndc.y * v.tanHalf);
}

fn depthTexel(uv: vec2f) -> vec2i {
  let size = vec2f(textureDimensions(inputTexture1));
  return clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1));
}

// View-plane distance at uv, or a negative number where there is no surface.
fn viewDepth(uv: vec2f) -> f32 {
  let d = textureLoad(inputTexture1, depthTexel(uv), 0).r;
  return select(d * params.far, -1.0, d >= 0.9999 || d <= 0.0);
}

fn worldAt(v: View, uv: vec2f, z: f32) -> vec3f {
  let ray = rayAt(v, uv);
  return params.eye + ray * (z / max(dot(ray, v.forward), 1e-4));
}

// World point → (uv, view-plane distance); z ≤ 0 means behind the camera.
fn project(v: View, world: vec3f) -> vec3f {
  let rel = world - params.eye;
  let z = dot(rel, v.forward);
  let x = dot(rel, v.right) / (max(z, 1e-4) * v.tanHalf * v.aspect);
  let y = dot(rel, v.up) / (max(z, 1e-4) * v.tanHalf);
  return vec3f(x * 0.5 + 0.5, 0.5 - y * 0.5, z);
}

fn ignHash(pixel: vec2f) -> f32 {
  return fract(52.9829189 * fract(dot(pixel, vec2f(0.06711056, 0.00583715))));
}

const TAPS: u32 = 48u;

fn focusAt() -> f32 {
  if (params.focusDistance > 0.0) { return params.focusDistance; }
  let centre = viewDepth(vec2f(0.5));
  return select(centre, 30.0, centre < 0.0);
}

fn circleAt(z: f32, focus: f32) -> f32 {
  if (z < 0.0) { return params.maxRadius; }
  let defocus = abs(1.0 / max(focus, 0.1) - 1.0 / max(z, 0.1)) * focus;
  return clamp(defocus * params.aperture * 10.0, 0.0, params.maxRadius);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let centre = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let z = viewDepth(uv);
  let focus = focusAt();
  let coc = circleAt(z, focus);
  if (coc < 0.5) { return centre; }
  let texel = 1.0 / frameU.resolution;
  var sum = centre.rgb;
  var weight = 1.0;
  for (var i = 1u; i < TAPS; i = i + 1u) {
    let radius = sqrt(f32(i) / f32(TAPS)) * coc;
    let angle = f32(i) * 2.39996323;
    let offset = vec2f(cos(angle), sin(angle)) * radius * texel;
    let tapZ = viewDepth(uv + offset);
    let tapCoc = circleAt(tapZ, focus);
    // A tap contributes if ITS blur reaches this pixel (so an in-focus foreground stays out).
    let w = smoothstep(radius - 1.0, radius + 1.0, max(tapCoc, select(coc, 0.0, tapZ >= 0.0 && tapZ < z - 1.0)));
    sum = sum + textureSampleLevel(inputTexture, inputSampler, uv + offset, 0.0).rgb * w;
    weight = weight + w;
  }
  return vec4f(sum / weight, centre.a);
}

struct Params {
  bars: f32, // @default 3  Radiance of the vertical light bars.
  barCount: f32, // @default 22  Bars around the horizon.
  roof: f32, // @default 0.006  Radiance of the roof.
  floor: f32, // @default 0.002  Radiance below the horizon.
  white: f32, // @default 0  1 = the white cyc room instead.
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

fn barHash(i: f32) -> f32 {
  return fract(sin(i * 91.3458 + 7.1) * 47453.5453);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let unused = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).a * 0.0;
  let phi = (uv.x - 0.5) * 6.2831853;
  let theta = uv.y * 3.1415927;
  let d = vec3f(sin(theta) * sin(phi), cos(theta), -sin(theta) * cos(phi));
  if (params.white > 0.5) {
    let wall = mix(0.55, 1.0, smoothstep(-0.3, 0.4, d.y));
    return vec4f(vec3f(wall * 1.6) + vec3f(unused), 1.0);
  }
  var radiance = mix(vec3f(params.floor), vec3f(params.roof), smoothstep(-0.05, 0.2, d.y));
  // Vertical bars: each its own azimuth jitter, width and height.
  let slot = uv.x * params.barCount;
  let index = floor(slot);
  let within = fract(slot) - 0.5 - (barHash(index) - 0.5) * 0.6;
  let width = 0.05 + 0.06 * barHash(index + 3.0);
  let top = 0.1 + 0.35 * barHash(index + 7.0);
  let lit = step(0.35, barHash(index + 11.0));
  let bar = smoothstep(width, width * 0.4, abs(within)) * smoothstep(-0.08, -0.04, d.y) * (1.0 - smoothstep(top - 0.04, top, d.y)) * lit;
  radiance = radiance + vec3f(0.92, 0.96, 1.0) * params.bars * bar;
  return vec4f(radiance + vec3f(unused), 1.0);
}

struct Params {
  range: f32, // @default 16  RGBM range the picture was packed with.
  gain: f32, // @default 1  Radiance scale.
  turn: f32, // @default 0  Rotation about the vertical, fraction of a revolution.
  crush: f32, // @default 0  0 keeps the room; 1 keeps only what is brighter than 1.
  desaturate: f32, // @default 0.6  Chroma removed (the grade wants steel, not sunset).
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let p = textureSampleLevel(inputTexture, inputSampler, vec2f(fract(uv.x + params.turn), uv.y), 0.0);
  var c = p.rgb * p.a * params.range;
  let luma = dot(c, vec3f(0.2126, 0.7152, 0.0722));
  c = mix(c, vec3f(luma), params.desaturate);
  c = c * mix(1.0, smoothstep(0.3, 1.5, luma), params.crush);
  return vec4f(c * params.gain, 1.0);
}

struct Params {
  refract: f32, // @default 0.012  Refraction offset, fraction of the frame, at full normal tilt.
  dispersion: f32, // @default 0.25  Extra offset for red over blue (a hint of rainbow at the edges).
  reflect: f32, // @default 1  Reflection gain.
  tint: f32, // @default 0.92  Transmission (the cover absorbs a little).
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;

fn texel(t: texture_2d<f32>, uv: vec2f) -> vec2i {
  let size = vec2f(textureDimensions(t));
  return clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let base = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let g = textureLoad(inputTexture2, texel(inputTexture2, uv), 0);
  // glass: a surface (a > 0) that is glossy (the occluders carry roughness 1)
  let isGlass = step(0.001, g.a) * step(g.a, 0.2);
  if (isGlass <= 0.0) { return base; }
  let n = normalize(g.rgb * 2.0 - 1.0);
  let o = n.xy * vec2f(1.0, -1.0) * params.refract;
  let r = textureSampleLevel(inputTexture, inputSampler, uv + o * (1.0 + params.dispersion), 0.0).r;
  let gg = textureSampleLevel(inputTexture, inputSampler, uv + o, 0.0).g;
  let b = textureSampleLevel(inputTexture, inputSampler, uv + o * (1.0 - params.dispersion), 0.0).b;
  let refl = textureSampleLevel(inputTexture1, inputSampler, uv, 0.0).rgb;
  return vec4f(vec3f(r, gg, b) * params.tint + refl * params.reflect, base.a);
}

struct Params {
  sheen: f32, // @default 0.06  Fresnel sheen radiance.
  glint: f32, // @default 3  Radiance of the glints (the room's bright shapes in the glass).
  tint: vec3f, // @default 1  Colour of the reflection.
};

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceDefaults(s);
  let v = normalize(s.eye - s.world);
  let n = normalize(s.normal);
  let nv = clamp(abs(dot(n, v)), 0.0, 1.0);
  let fresnel = 0.04 + 0.96 * pow(1.0 - nv, 5.0);
  let r = reflect(-v, n);
  // the room: a bright horizon band (the other cars' lamps, the doors) and two overhead fittings
  let band = smoothstep(0.12, 0.02, abs(r.y - 0.05)) * (0.6 + 0.4 * sin(atan2(r.x, r.z) * 7.0));
  let top = pow(max(dot(r, normalize(vec3f(0.3, 1.0, 0.2))), 0.0), 400.0) + pow(max(dot(r, normalize(vec3f(-0.4, 0.9, -0.3))), 0.0), 300.0);
  o.albedo = vec4f(0.0, 0.0, 0.0, 1.0);
  o.emissive = p.tint * (fresnel * p.sheen * 10.0 + (band + top) * p.glint * (0.25 + fresnel));
  return o;
}

struct Params {
  exposure: f32, // @default 0  Stops.
  black: f32, // @default 0.035  Display level crushed to zero (the toe cut).
  contrast: f32, // @default 1.25  S-curve slope around mid-grey.
  saturation: f32, // @default 0.28  Chroma kept (the reference keeps almost none).
  keepWarm: f32, // @default 0.5  Chroma kept on strongly saturated warm sources (flare contamination).
  bleach: f32, // @default 0.35  Bleach-bypass mix.
  steel: vec3f, // @default 1  Tint pushed into the upper mids.
  shadowTint: vec3f, // @default 1  Tint in the shadows (neutral to cool only).
  split: f32, // @default 0.5  Strength of both tints.
  grain: f32, // @default 0.03  Grain amount.
  grainSize: f32, // @default 1.3  Grain size in pixels.
  lift: f32, // @default 0  Display-level lift (the cyc's overexposed floor).
};
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;

fn gradeHash(p: vec3f) -> f32 {
  var q = fract(p * vec3f(0.1031, 0.1030, 0.0973));
  q = q + dot(q, q.yxz + 33.33);
  return fract((q.x + q.y) * q.z);
}

// A filmic shoulder (Hable's) on scene-linear light, normalised to white at 11.2.
fn hable(x: vec3f) -> vec3f {
  let a = 0.15; let b = 0.5; let c = 0.1; let d = 0.2; let e = 0.02; let f = 0.3;
  return ((x * (a * x + c * b) + d * e) / (x * (a * x + b) + d * f)) - e / f;
}

fn luma(c: vec3f) -> f32 {
  return dot(c, vec3f(0.2126, 0.7152, 0.0722));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let hdr = max(textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb, vec3f(0.0)) * exp2(params.exposure);
  // Chroma decision BEFORE the curve: a strongly saturated warm source keeps some colour.
  let hl = luma(hdr);
  let chroma = (max(hdr.r, max(hdr.g, hdr.b)) - min(hdr.r, min(hdr.g, hdr.b))) / max(max(hdr.r, max(hdr.g, hdr.b)), 1e-4);
  let warm = smoothstep(0.35, 0.8, chroma) * step(hdr.b, hdr.r);
  let keep = mix(params.saturation, max(params.saturation, params.keepWarm), warm);
  var c = hable(hdr * 2.0) / hable(vec3f(11.2));
  // display-ish space for the grade
  c = pow(clamp(c, vec3f(0.0), vec3f(1.0)), vec3f(1.0 / 2.2));
  let y0 = luma(c);
  c = mix(vec3f(y0), c, keep);
  // bleach bypass: overlay the picture with its own luma
  let y = luma(c);
  let overlay = select(1.0 - 2.0 * (1.0 - c) * (1.0 - y), 2.0 * c * y, c < vec3f(0.5));
  c = mix(c, overlay, params.bleach);
  // contrast S around mid-grey, then the black crush
  c = clamp((c - 0.45) * params.contrast + 0.45, vec3f(0.0), vec3f(1.0));
  c = clamp((c - params.black) / (1.0 - params.black), vec3f(0.0), vec3f(1.0));
  // split: cool steel into the upper mids, neutral-to-cool shadows
  let yl = luma(c);
  let upper = smoothstep(0.35, 0.8, yl) * (1.0 - smoothstep(0.9, 1.0, yl));
  let low = 1.0 - smoothstep(0.0, 0.3, yl);
  c = c * mix(vec3f(1.0), params.steel, upper * params.split) * mix(vec3f(1.0), params.shadowTint, low * params.split);
  c = c + vec3f(params.lift) * (1.0 - c);
  // grain: luma-weighted, heavier in the blacks, a new pattern each frame
  let px = floor(uv * frameU.resolution / max(params.grainSize, 0.5));
  let n = gradeHash(vec3f(px, frameU.absFrame)) + gradeHash(vec3f(px + 17.0, frameU.absFrame * 1.7)) - 1.0;
  c = c + vec3f(n) * params.grain * (0.35 + 0.65 * (1.0 - luma(c)));
  c = clamp(c, vec3f(0.0), vec3f(1.0));
  return vec4f(pow(c, vec3f(2.2)), 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
// T1400b — On Nothing haze (generated by src/projects/on-nothing/atmosphere.ts from the GLB's lamps).
struct Params {
  eye: vec3f, // @default 0  Camera position (drive from the camera).
  aim: vec3f, // @default 0  Camera look-at (drive from the camera).
  fov: f32, // @default 50  Camera vertical field of view, degrees.
  far: f32, // @default 400  Camera far plane (depth arrives as distance ÷ far).
  roll: f32, // @default 0  Camera roll, degrees (drive from the camera).
  density: f32, // @default 0.02  Scattering per metre.
  anisotropy: f32, // @default 0.7  Henyey-Greenstein g: how forward-peaked (toward the lens) the scatter is.
  ambient: vec3f, // @default 0  Radiance the haze carries everywhere (the room's own faint light).
  reach: f32, // @default 40  Longest march where a ray hits nothing, metres.
  head: f32, // @default 1  Headlight scatter gain.
  tube: f32, // @default 1  LED tube scatter gain.
  back: f32, // @default 1  Backlight scatter gain.
  drift: f32, // @default 0.25  Depth of the slow density variation.
  core: f32, // @default 0.08  Metres: the soft core radius around each source (caps 1/d²).
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

// T1383b: the camera's right vector with its ROLL — world up turned about the view axis by
// roll degrees (Rodrigues, right-handed about the camera's +z: the angle is negated about forward),
// exactly as camera.ts guardedRolledUp builds the render's view (T1433b).
fn rolledRight(forward: vec3f, rollDeg: f32) -> vec3f {
  var up = select(vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0), abs(forward.y) > 0.999);
  let t = radians(-rollDeg);
  up = up * cos(t) + cross(forward, up) * sin(t) + forward * dot(forward, up) * (1.0 - cos(t));
  return normalize(cross(forward, up));
}

struct View {
  forward: vec3f,
  right: vec3f,
  up: vec3f,
  tanHalf: f32,
  aspect: f32,
};

fn makeView() -> View {
  var v: View;
  v.forward = normalize(params.aim - params.eye);
  v.right = rolledRight(v.forward, params.roll);
  v.up = cross(v.right, v.forward);
  v.tanHalf = tan(radians(params.fov) * 0.5);
  v.aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  return v;
}

fn rayAt(v: View, uv: vec2f) -> vec3f {
  let ndc = vec2f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
  return normalize(v.forward + v.right * ndc.x * v.tanHalf * v.aspect + v.up * ndc.y * v.tanHalf);
}

fn depthTexel(uv: vec2f) -> vec2i {
  let size = vec2f(textureDimensions(inputTexture1));
  return clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1));
}

// View-plane distance at uv, or a negative number where there is no surface.
fn viewDepth(uv: vec2f) -> f32 {
  let d = textureLoad(inputTexture1, depthTexel(uv), 0).r;
  return select(d * params.far, -1.0, d >= 0.9999 || d <= 0.0);
}

fn worldAt(v: View, uv: vec2f, z: f32) -> vec3f {
  let ray = rayAt(v, uv);
  return params.eye + ray * (z / max(dot(ray, v.forward), 1e-4));
}

// World point → (uv, view-plane distance); z ≤ 0 means behind the camera.
fn project(v: View, world: vec3f) -> vec3f {
  let rel = world - params.eye;
  let z = dot(rel, v.forward);
  let x = dot(rel, v.right) / (max(z, 1e-4) * v.tanHalf * v.aspect);
  let y = dot(rel, v.up) / (max(z, 1e-4) * v.tanHalf);
  return vec3f(x * 0.5 + 0.5, 0.5 - y * 0.5, z);
}

fn ignHash(pixel: vec2f) -> f32 {
  return fract(52.9829189 * fract(dot(pixel, vec2f(0.06711056, 0.00583715))));
}

const LIGHTS: u32 = 11u;
const L_POS = array<vec3f, 11>(
  vec3f(0.70081, 0.93676, -0.26165),
  vec3f(-0.70080, 0.93676, -0.26162),
  vec3f(-3.20056, 0.92948, -1.12989),
  vec3f(-4.49944, 0.92947, -1.13011),
  vec3f(4.26930, 0.69717, -0.97001),
  vec3f(3.17070, 0.69690, -0.96999),
  vec3f(-3.50000, 6.60000, -5.00000),
  vec3f(3.00000, 6.60000, -5.00000),
  vec3f(-1.00000, 6.60000, -10.00000),
  vec3f(5.50000, 6.60000, -10.00000),
  vec3f(-6.00000, 6.60000, -10.00000));
const L_DIR = array<vec3f, 11>(
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -1.00000, 0.00000),
  vec3f(0.00000, -1.00000, 0.00000),
  vec3f(0.00000, -1.00000, 0.00000),
  vec3f(0.00000, -1.00000, 0.00000),
  vec3f(0.00000, -1.00000, 0.00000));
const L_COLOR = array<vec3f, 11>(
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(1.00000, 0.72000, 0.50000),
  vec3f(1.00000, 0.72000, 0.50000),
  vec3f(1.00000, 0.72000, 0.50000),
  vec3f(1.00000, 0.72000, 0.50000),
  vec3f(1.00000, 0.72000, 0.50000));
const L_SHAPE = array<vec4f, 11>(
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(-2.00000, -1.00000, 1.0, 0.0),
  vec4f(-2.00000, -1.00000, 1.0, 0.0),
  vec4f(-2.00000, -1.00000, 1.0, 0.0),
  vec4f(-2.00000, -1.00000, 1.0, 0.0),
  vec4f(-2.00000, -1.00000, 1.0, 0.0));
const STEPS: u32 = 72u;

fn hg(cosTheta: f32, g: f32) -> f32 {
  let g2 = g * g;
  return (1.0 - g2) / (12.566371 * pow(max(1.0 + g2 - 2.0 * g * cosTheta, 1e-4), 1.5));
}

fn groupGain(group: f32) -> f32 {
  return select(select(params.back, params.tube, group < 1.5), params.head, group < 0.5);
}

fn driftDensity(p: vec3f, t: f32) -> f32 {
  let q = p * 0.35 + vec3f(t * 0.05, 0.0, t * 0.03);
  let n = sin(q.x * 1.3 + sin(q.z * 0.9)) * sin(q.z * 1.1 + sin(q.y * 1.7 + q.x * 0.4)) * 0.5 + 0.5;
  return 1.0 + (n - 0.5) * 2.0 * params.drift;
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let lit = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let v = makeView();
  let ray = rayAt(v, uv);
  let z = viewDepth(uv);
  let distance = select(params.reach, z / max(dot(ray, v.forward), 1e-4), z > 0.0);
  let jitter = ignHash(uv * frameU.resolution + vec2f(frameU.absFrame * 5.3, 0.0));
  let dt = distance / f32(STEPS);
  var scatter = vec3f(0.0);
  var optical = 0.0;
  for (var i = 0u; i < STEPS; i = i + 1u) {
    let travel = (f32(i) + jitter) * dt;
    let p = params.eye + ray * travel;
    let sigma = params.density * driftDensity(p, frameU.absTime);
    var inscatter = params.ambient;
    for (var k = 0u; k < LIGHTS; k = k + 1u) {
      let toP = p - L_POS[k];
      let d2 = dot(toP, toP);
      let l = toP * inverseSqrt(max(d2, 1e-6));
      let shape = L_SHAPE[k];
      let cone = select(smoothstep(shape.x, shape.y, dot(l, L_DIR[k])), 1.0, shape.x < -1.5);
      if (cone <= 0.0) { continue; }
      inscatter = inscatter + L_COLOR[k] * groupGain(shape.z) * cone * hg(dot(l, -ray), params.anisotropy) / (d2 + params.core * params.core);
    }
    scatter = scatter + inscatter * sigma * exp(-optical) * dt;
    optical = optical + sigma * dt;
  }
  return vec4f(lit.rgb * exp(-optical) + scatter, lit.a);
}

struct Params {
  k: f32, // @default 0.13  Barrel distortion (height units², normalised at the side edges).
  edgeBlur: f32, // @default 0.018  Edge smear at the side edges, fraction of the frame height.
  swirl: f32, // @default 0.7  0 radial .. 1 tangential edge smear.
  aberration: f32, // @default 0.004  Lateral colour at the side edges, fraction of the radius.
  vignette: f32, // @default 0.5  Darkening at the corners.
};
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
